INSERT INTO entries (collection,id,data,sort,updated_at) VALUES ('careers','job-01','{"id":"job-01","status":"published","title":"Production Engineer","titleAr":"مهندس إنتاج","dept":"Production","deptAr":"الإنتاج","type":"Full-time","typeAr":"دوام كامل","location":"Jeddah, KSA","locationAr":"جدة، السعودية","email":"production.jobs@printopack.com.sa","summary":"Run and improve our rotogravure and lamination lines, keeping output on-spec and on-time.","summaryAr":"تشغيل وتحسين خطوط الطباعة الروتوغرافية والتصفيح، مع الحفاظ على مطابقة الإنتاج للمواصفات وتسليمه في وقته.","requirements":"BSc in mechanical or industrial engineering.\n3+ years on rotogravure or flexible-packaging lines.\nA strong grasp of print quality and process control.","requirementsAr":"بكالوريوس في الهندسة الميكانيكية أو الصناعية.\nخبرة 3 سنوات فأكثر على خطوط الطباعة الروتوغرافية أو التغليف المرن.\nإلمام قوي بجودة الطباعة وضبط العمليات."}',0,1753000000000);
INSERT INTO entries (collection,id,data,sort,updated_at) VALUES ('careers','job-02','{"id":"job-02","status":"published","title":"Quality Control Specialist","titleAr":"أخصائي مراقبة الجودة","dept":"Quality","deptAr":"الجودة","type":"Full-time","typeAr":"دوام كامل","location":"Jeddah, KSA","locationAr":"جدة، السعودية","email":"quality.jobs@printopack.com.sa","summary":"Check every run against our food-safety and print standards before it ships.","summaryAr":"فحص كل تشغيلة وفق معايير سلامة الغذاء والطباعة قبل شحنها.","requirements":"Background in food-contact materials and lab testing.\nFamiliarity with BRCGS or similar standards.\nA meticulous, documentation-driven approach.","requirementsAr":"خلفية في المواد الملامِسة للأغذية والفحص المخبري.\nمعرفة بمعيار BRCGS أو ما يماثله.\nمنهجية دقيقة قائمة على التوثيق."}',1,1753000000000);
INSERT INTO entries (collection,id,data,sort,updated_at) VALUES ('careers','job-03','{"id":"job-03","status":"draft","title":"Sales Account Manager","titleAr":"مدير حسابات مبيعات","dept":"Sales","deptAr":"المبيعات","type":"Full-time","typeAr":"دوام كامل","location":"Regional","locationAr":"إقليمي","email":"sales.jobs@printopack.com.sa","summary":"Grow relationships with food, beverage and consumer brands across the region.","summaryAr":"تنمية العلاقات مع علامات الأغذية والمشروبات والمنتجات الاستهلاكية في المنطقة.","requirements":"5+ years of B2B packaging or FMCG sales.\nExisting brand relationships are a plus.\nFluent Arabic and English.","requirementsAr":"خبرة 5 سنوات فأكثر في مبيعات التغليف أو السلع الاستهلاكية (B2B).\nوجود علاقات قائمة مع العلامات ميزة إضافية.\nإتقان العربية والإنجليزية."}',2,1753000000000);
