INSERT INTO entries (collection,id,data,sort,updated_at) VALUES ('standard','std-01','{"id":"std-01","title":"Developed for your line","titleAr":"مطوّر لخطكم","text":"Structure, barrier and seal are engineered around your product and your filling equipment, not a catalogue item.","textAr":"يُهندَس التركيب والحاجز والغلق حول منتجكم ومعدات التعبئة لديكم، لا كصنفٍ جاهز من كتالوج."}',0,1753000000000);
INSERT INTO entries (collection,id,data,sort,updated_at) VALUES ('standard','std-02','{"id":"std-02","title":"Printed in-house","titleAr":"مطبوع داخلياً","text":"Rotogravure print with cylinders engraved under our own roof, from artwork to press without hand-offs.","textAr":"طباعة روتوغرافير بأسطوانات تُحفر تحت سقفنا، من التصميم إلى الطباعة دون وسطاء."}',1,1753000000000);
INSERT INTO entries (collection,id,data,sort,updated_at) VALUES ('standard','std-03','{"id":"std-03","title":"Food-safe by default","titleAr":"آمن غذائياً بطبيعته","text":"Food-grade materials and a quality system that follows every order from laminate to delivery.","textAr":"مواد ملائمة للأغذية ونظام جودة يرافق كل طلبٍ من التصفيح حتى التسليم."}',2,1753000000000);
INSERT INTO entries (collection,id,data,sort,updated_at) VALUES ('values','val-01','{"id":"val-01","title":"Quality without compromise","titleAr":"جودةٌ بلا تنازل","text":"Every reel is held to the Printopack standard, from incoming substrate to final dispatch.","textAr":"كل لفّةٍ تخضع لمعيار برنتوباك، من استلام المواد حتى التسليم النهائي."}',0,1753000000000);
INSERT INTO entries (collection,id,data,sort,updated_at) VALUES ('values','val-02','{"id":"val-02","title":"Responsible by design","titleAr":"المسؤولية بالتصميم","text":"Food-safe materials, solvent recovery and efficient production run through everything we make.","textAr":"موادٌ آمنة غذائياً واسترجاعٌ للمذيبات وإنتاجٌ كفؤ في كل ما نصنع."}',1,1753000000000);
INSERT INTO entries (collection,id,data,sort,updated_at) VALUES ('values','val-03','{"id":"val-03","title":"Partnership, not supply","titleAr":"شراكةٌ لا مجرّد توريد","text":"We advise on structure and print from the first brief, so the packaging fits the product and the line.","textAr":"نقدّم المشورة في البنية والطباعة منذ أول موجز، ليناسب التغليف المنتج وخط الإنتاج."}',2,1753000000000);
INSERT INTO entries (collection,id,data,sort,updated_at) VALUES ('values','val-04','{"id":"val-04","title":"Built to deliver","titleAr":"التزامٌ بالتسليم","text":"Planned materials and export logistics mean orders land on time, run after run.","textAr":"تخطيطٌ للمواد ولوجستيات التصدير يضمن وصول الطلبات في وقتها، تشغيلةً بعد أخرى."}',3,1753000000000);
INSERT INTO singletons (key,data,updated_at) VALUES ('about','{"heroTitle":"Where technology meets vision.","heroTitleAr":"حيث تلتقي التقنية بالرؤية.","heroSub":"A global leader in developing and producing responsible packaging.","heroSubAr":"رائدون عالمياً في تطوير وإنتاج تغليف مسؤول.","historyTitle":"From one line in 1997 to brands across 35 countries.","historyTitleAr":"من خطٍّ واحد عام 1997 إلى علاماتٍ في 35 دولة.","history":"Printopack, the trading name of Saudi Modern Packaging Factory Co. Ltd., was established in 1997 in Jeddah. What began as a single flexible-packaging operation has grown into a full service converter, with in-house rotogravure printing, cylinder engraving, bag making, finishing and solvent recovery, all under one roof.\n\nToday the company is family-owned and Saudi-operated, serving food, beverage, pharmaceutical and consumer brands across more than 35 countries through ten regional offices.","historyAr":"تأسّست برنتوباك، الاسم التجاري لمصنع التغليف السعودي الحديث المحدود، عام 1997 في جدة. وما بدأ كخطٍّ واحد للتغليف المرن نما ليصبح مصنعاً متكامل الخدمات يضمّ الطباعة الروتوغرافية وحفر الأسطوانات وصناعة الأكياس والتشطيب واسترجاع المذيبات، جميعها تحت سقفٍ واحد.\n\nواليوم، تملك الشركةَ عائلةٌ وتُدار سعودياً، وتخدم علامات الأغذية والمشروبات والأدوية والسلع الاستهلاكية في أكثر من 35 دولة عبر عشرة مكاتب إقليمية.","ownership":"Saudi Modern Packaging Factory Co. Ltd.","ownershipAr":"مصنع التغليف السعودي الحديث المحدود.","mission":"The driving force behind brands'' packaging evolution.","missionAr":"القوة الدافعة وراء تطوّر تغليف العلامات التجارية.","missionBody":"At Printopack, our mission is to be the driving force behind brands'' packaging evolution. With a legacy of expertise in flexible packaging solutions since 1997, we are dedicated to designing, developing, and producing responsible packaging that transcends mere functionality.\n\nThrough innovative design, cutting-edge technology, and a commitment to sustainability, we empower brands to create packaging experiences that captivate consumers and align with their values, nurturing lasting partnerships with businesses across the globe.","missionBodyAr":"رسالتنا في برنتوباك أن نكون القوة الدافعة وراء تطوّر تغليف العلامات التجارية. وبإرثٍ من الخبرة في حلول التغليف المرن منذ عام 1997، نلتزم بتصميم تغليفٍ مسؤول وتطويره وإنتاجه بما يتجاوز مجرّد الوظيفة.\n\nوعبر التصميم المبتكر والتقنيات المتقدّمة والالتزام بالاستدامة، نُمكّن العلامات من ابتكار تجارب تغليفٍ تأسر المستهلكين وتنسجم مع قيمهم، ونرعى شراكاتٍ دائمة مع الأعمال حول العالم.","vision":"Empowering brands through creative packaging excellence.","visionAr":"تمكين العلامات التجارية عبر التميّز الإبداعي في التغليف.","visionBody":"Printopack''s vision is to redefine packaging as a transformative brand experience, fostering a sustainable and captivating future for industries worldwide. Our dedication to innovative solutions and responsible practices will shape a world where packaging becomes an enduring testament to brand values and consumer trust.\n\nWe envision a world where packaging transcends its functional role, becoming an artful representation of brand values, consumer trust, and environmental responsibility, led by responsible practices that resonate with consumers and contribute to a more sustainable planet.","visionBodyAr":"تسعى رؤية برنتوباك إلى إعادة تعريف التغليف بوصفه تجربةً تُحوِّل العلامة التجارية، وترسم مستقبلاً مستداماً وجاذباً للصناعات حول العالم. والتزامنا بالحلول المبتكرة والممارسات المسؤولة يصنع عالماً يغدو فيه التغليف شاهداً راسخاً على قيم العلامة وثقة المستهلك.\n\nنتطلّع إلى عالمٍ يتجاوز فيه التغليف دوره الوظيفي ليصبح تعبيراً فنياً عن قيم العلامة وثقة المستهلك والمسؤولية البيئية، تقوده ممارساتٌ مسؤولة تلقى صدى لدى المستهلكين وتُسهم في كوكبٍ أكثر استدامة.","statOffices":"10","statCountries":"35","statFounded":"1997","statEmployees":"400","statAvgExp":"14","statCustomers":"1000"}',1753000000000);
INSERT INTO singletons (key,data,updated_at) VALUES ('settings','{"company":"Printopack - Saudi Modern Packaging Factory Co. Ltd.","companyAr":"برنتوباك - مصنع التغليف السعودي الحديث المحدود","phone":"+966 12 608 1074","fax":"+966 12 608 1082","email":"info@printopack.com.sa","hours":"9:00 AM to 5:00 PM","address":"Industrial Area 5, Unit 10, 8508, Jeddah 22428, Saudi Arabia","addressAr":"المنطقة الصناعية 5، وحدة 10، 8508، جدة 22428، المملكة العربية السعودية","maxImageKb":"400","addressShort":"Industrial Area 5, Jeddah, Saudi Arabia","addressShortAr":"المنطقة الصناعية 5، جدة، السعودية"}',1753000000000);
